/**
 * One model turn and one tool dispatch: the policy picks the tools and the model, the
 * transport answers, and every call goes through the core registry so the capability
 * gate holds at call time. Plus the one forced no-tools turn a run that never answered
 * gets before it settles.
 */

import type { ToolSchema } from "@builderforce/agent-tools";
import { malformedCallOutcome, type LoopDispatchResult, type LoopTurnResult, type ParsedToolCall, type TurnContext } from "@builderforce/agent-loop";
import { reduceRunPolicy } from "@builderforce/run-policy";
import { ModelTransportError, type ContextPack, type RunPolicy, type ModelCompletion, type ModelRequest, type RunMessage, type RunPorts, type RunState } from "./contract.js";
import { ownsCall, registryOf } from "./runCatalog.js";
import { killedResults, nativeResults, type NativeResult } from "./runRows.js";
import { isTransportFailure } from "./surface.js";
import type { PolicyHooks } from "./policy/index.js";
import type { SynthesisWhy } from "./policy/hooks.js";
import type { ForcedTurnResult } from "./policy/guards/forced/types.js";
import { routeAround, turnSucceeded, type TurnAsk } from "./policy/model/handoff.js";
import { reaskAsCoder } from "./policy/model/reask.js";
import { interruptedResult, runToolWithWatch, stoppedResult, type InterruptWatch } from "./policy/steering/index.js";
import { toolsTokensOf } from "./policy/compaction/compact.js";
import { capToolResult, resultCapFor } from "./policy/tools/index.js";
import { renderTaskState } from "./policy/tools/taskState.js";
import { assignedWorkSection } from "./workPlan.js";
import { appendRows, currentView, emit, policyContext, type RunAgentInput, type TurnFacts } from "./runContext.js";
import { tallyTurn, type RunTally } from "./telemetry/runTally.js";
import { measureTurnTail } from "./turnTail.js";
import { measureWorkflow, workflowScope } from "./telemetry/workflowMetrics.js";
import { isSpawnTool } from "./policy/subagents/delegationRequest.js";
import { blocksChildSpawn, CHILD_SPAWN_REFUSAL } from "./policy/subagents/child.js";
import { withVolatileTail } from "./turnContext.js";
import { specValidationSection } from "./policy/verify/specValidation.js";

/**
 * What the step decided about its menu before the request is built: the schemas the policy selected, and - when the surface forced the
 * turn (`PlatformTools.turn`) - the tool choice it requires and the brief sections that ride the request's volatile tail.
 */
export interface TurnSelection {
  tools: readonly ToolSchema[] | void;
  toolChoice?: "required";
  tail?: readonly string[];
  /**
   * The run's final report — no tools, and never judged as a stall: A3's `finish` (the guards', which also keeps the run's own
   * role) or the surface's own final turn (`TurnMenu.final`, routed as any no-tool turn the surface asks).
   */
  final?: true;
  /** Who made the turn final: the guards' A3 finish (spent by `finalTurnDone` once answered) or the surface's menu. */
  finalBy?: "guards" | "surface";
  /** What the guards' forced-turn ladder decided for this step (`GuardsHook.forcedTurn`). */
  forced?: ForcedTurnResult;
  /**
   * The provider failed and the model policy re-asks (`recoverFailure`): the next step takes the SAME forced turn instead of
   * deciding a new one, so a retry never spends the forced turn (a hand-off or finish the ladder had already decided).
   */
  retried?: true;
}

/** What a surface's own tool answered, for the no-progress count: from its read cache, or only conversational. */
export const callKinds = new WeakMap<object, "cached" | "neutral">();
export const observedToolData = new WeakMap<object, unknown>();

/** Non-transport exceptions that failed a turn, per run: the surface decides whether they are a failure or an eviction. */
const causes = new WeakMap<object, unknown>();

/** Whether the SURFACE says an exception a port threw is a resumable interruption (it re-arms the run) rather than the run's failure. A transport failure is never one. */
export function isResumable(input: RunAgentInput, err: unknown): boolean {
  return !(err instanceof ModelTransportError) && input.ports.store.isResumable?.(err) === true;
}
export function causeOf(state: object): unknown {
  return causes.get(state);
}

export { offeredSchemas, ownsCall } from "./runCatalog.js";

/** The hard cap on the forced synthesis turn's answer — the source's bounded extra call. */
const SYNTHESIS_MAX_TOKENS = 1_000;

function measureModelRequest(input: RunAgentInput, step: number, request: ModelRequest, operation: 'model_request' | 'model_synthesis' = 'model_request') {
  return measureWorkflow(input.ports.events, { ...workflowScope(input, step), operation }, 'kernel',
    () => input.ports.model.complete(request, input.signal), undefined, input.signal);
}

/**
 * What served a turn is what the next one asks for - except `default` (the gateway's own
 * auto label, not a model) and under a strict pin, which the policy keeps. The ONE write of
 * the served model, for the turn and for the closing synthesis alike.
 */
function adoptServedModel(policy: RunPolicy, state: RunState, served: string | undefined): void {
  // A plain model policy (`RunPolicy.modelStart.plain`: the Brain's) holds no model of its own between turns, as its own loop never
  // did: a held model would also close the analysis -> code re-ask, which only a run holding none earns.
  if (policy.modelStart?.plain) return;
  if (served && served !== "default" && !state.model.strictPin) state.model = { ...state.model, model: served };
}

/** What a request carries beyond the transcript and the tools: the turn's ask of the transport. */
function withoutToolChoiceIf(drop: boolean, fields: Partial<ModelRequest>): Partial<ModelRequest> {
  if (!drop || !("toolChoice" in fields)) return fields;
  const { toolChoice: _dropped, ...rest } = fields;
  return rest;
}

function askFields(ask: Partial<TurnAsk> | undefined): Partial<ModelRequest> {
  if (!ask) return {};
  return {
    ...(ask.role ? { role: ask.role } : {}),
    ...(ask.phase ? { phase: ask.phase } : {}),
    ...(ask.toolChoice ? { toolChoice: ask.toolChoice } : {}),
    ...(ask.strict ? { strict: true } : {}),
    ...(ask.excludeModels && ask.excludeModels.length > 0 ? { excludeModels: ask.excludeModels } : {}),
  };
}

/**
 * One model turn: the policy picks the tools and the model, the memory policy writes the
 * brief, and the transport answers. The request carries the transcript plus this turn's
 * volatile tail (the pack, the brief and the surface's own sections) LAST — the tail is
 * never written into the transcript, so the cached prefix and the saved state never hold it.
 *
 * A transport that answers a failure the model policy routes around (a rate limit, a
 * window refusal, an outage — `ModelTransportError`) is asked ONCE more on the cascade
 * the policy chose (`completeUnderRunPolicy`, ported in `policy/model/handoff.ts`).
 */
export async function completeTurn(
  input: RunAgentInput,
  state: RunState,
  hooks: PolicyHooks,
  ctx: TurnContext<RunMessage>,
  offered: ToolSchema[],
  transcript: RunMessage[],
  pack: ContextPack,
  /** The step's tool selection when `beforeTurn` already made it (compaction charged those schemas), and what the surface forced on the turn. */
  made?: TurnSelection,
): Promise<LoopTurnResult> {
  const view = currentView(transcript, offered);
  const pctx = policyContext(input, state, view, ctx.step, ctx.stepInCall);
  const selected = made ? made.tools : await hooks.tools.select(pctx, offered);
  // An empty selection is a decision, not an absence: a module that returns `[]` has
  // chosen that this run may call nothing. Only `undefined` means "not my concern".
  const tools = selected ? [...selected] : offered;
  const advertisedSet = tools.map((t) => t.function?.name ?? "").join(",");
  if (state.advertisedSignature !== advertisedSet) {
    state.advertisedSignature = advertisedSet;
    await emit(input.ports.events, { kind: "context.tools", step: ctx.step, advertised: tools.length, catalog: offered.length, toolsTokens: toolsTokensOf(tools), loaded: state.loadedTools ?? [] });
  }
  // The model policy is asked about the tools this turn will ADVERTISE: a turn with none
  // is conversation, and asks for the `chat` role.
  // A3's final turn has no tools but is NOT conversation: it keeps the run's role and model (`PolicyContext.finalTurn`).
  // A surface's own final turn (`TurnMenu.final`) routes as the surface always asked it (a no-tool turn): only its judgement changes.
  const mctx = { ...pctx, tools, ...(made?.finalBy === "guards" ? { finalTurn: true as const } : {}) };
  const decision = await hooks.model.resolve(mctx);
  // The model ASKED for: the policy's pick - absent on purpose after a pin was released -
  // else, only when no policy spoke, the pin. Never the model a previous turn was served,
  // which would read every later turn as a downgrade from it.
  const model = decision ? decision.model : input.policy.pinnedModel;
  const brief = await hooks.memory.brief(pctx);
  const work = assignedWorkSection(state.work ?? []);
  const validation = specValidationSection(state);
  const sections = [...(input.ports.context.turnSections?.() ?? []), ...(work ? [`### Assigned work\n${work}`] : []), ...(validation ? [validation] : []), ...(made?.tail ?? [])];
  const fields = hooks.model.turnFields?.(mctx);
  const reasoning = hooks.guards.reasoning?.(pctx);

  // What the turn asks of the transport: the decision's role, strictness and exclusions, then the
  // policy's own turn fields (the run phase and a stall recovery's forced tool choice).
  const firstAsk: Partial<TurnAsk> = {
    ...(decision?.role ? { role: decision.role } : {}),
    ...(decision?.strict ? { strict: true } : {}),
    ...(decision?.excludeModels && decision.excludeModels.length > 0 ? { excludeModels: [...decision.excludeModels] } : {}),
    ...(fields ?? {}),
  };
  // `extra` rides the request as untagged rows before the volatile tail (the coder's hand-off brief): never in the transcript.
  const progressNote = renderTaskState(state.taskState);
  const requestFor = (askedModel: string | undefined, ask: Partial<TurnAsk> | undefined, extra: RunMessage[] = []): ModelRequest => ({
    messages: measureTurnTail(state, withVolatileTail(extra.length > 0 ? [...transcript, ...extra] : transcript, pack, brief ?? null, sections)),
    ...(askedModel ? { model: askedModel, strict: ask?.strict ?? false } : {}),
    ...(tools.length > 0 ? { tools } : {}),
    ...(decision?.maxTokens !== undefined ? { maxTokens: decision.maxTokens } : {}),
    // A tool choice means nothing without tools (and a provider may refuse it): a turn advertising none never sends one.
    ...withoutToolChoiceIf(tools.length === 0, askFields(ask)),
    ...(tools.length > 0 && made?.toolChoice && !ask?.toolChoice ? { toolChoice: made.toolChoice } : {}),
    ...(reasoning ? { reasoning } : {}),
    ...(progressNote ? { progress: progressNote } : {}),
  });

  let asked = model;
  let completion: ModelCompletion;
  // When the call that ANSWERED started — re-set before a retry or a re-ask — so the run policy times the serving model alone.
  let startedAt = Date.now();
  try {
    completion = await measureModelRequest(input, ctx.step, requestFor(model, firstAsk));
  } catch (err) {
    if (input.signal?.aborted) throw err;
    const reason = err instanceof Error ? err.message : String(err);
    if (isResumable(input, err)) causes.set(state, err);
    // A provider that broke is routed around - a model that already acted takes over, or
    // the gateway's pool is asked again without the broken one - before the turn is lost.
    if (isTransportFailure(err) && hooks.model.recoverFailure) {
      const route = hooks.model.recoverFailure(pctx, err.failure, err.failure.model ?? model, reason);
      if (route.kind === "retry") {
        if (route.note) appendRows(input, transcript, { role: "system", content: route.note });
        if (made) made.retried = true;
        return { skip: true };
      }
      return { failed: `provider failed: ${reason}` };
    }
    const routed = err instanceof ModelTransportError && err.routable ? routeAround(state, err.status) : null;
    if (!routed) return { failed: reason };
    await emit(input.ports.events, { kind: "model.cascade", step: ctx.step, from: routed.from, status: err instanceof ModelTransportError ? err.status ?? null : null, released: routed.released });
    asked = routed.retry.model;
    startedAt = Date.now();
    try {
      completion = await measureModelRequest(input, ctx.step, requestFor(routed.retry.model, routed.retry));
    } catch (retryErr) {
      if (input.signal?.aborted) throw retryErr;
      if (isResumable(input, retryErr)) causes.set(state, retryErr);
      return { failed: retryErr instanceof Error ? retryErr.message : String(retryErr) };
    }
  }

  // ANALYSIS -> CODE, at the exact turn it matters (`policy/model/reask.ts`): the planner's first code change is re-asked of the coder.
  const reask = reaskAsCoder(state, input.policy, completion, { role: firstAsk.role, hasTools: tools.length > 0 });
  if (reask) {
    await emit(input.ports.events, { kind: "model.coder_reask", step: ctx.step, ...(completion.model ? { model: completion.model } : {}) });
    asked = reask.ask.model;
    startedAt = Date.now();
    try {
      completion = await measureModelRequest(input, ctx.step, requestFor(reask.ask.model, reask.ask, [reask.brief]));
    } catch (err) {
      if (input.signal?.aborted) throw err;
      if (isResumable(input, err)) causes.set(state, err);
      return { failed: err instanceof Error ? err.message : String(err) };
    }
  }

  // The turn answered: the policy locks onto what served it (when configured to) and records it
  // proven when it acted - the hand-off a later stall or failure draws on; the served model is
  // then the run's current one.
  turnSucceeded(state, { acted: (completion.toolCalls ?? []).length > 0, durationMs: Date.now() - startedAt, ...(completion.model ? { model: completion.model } : {}) });
  adoptServedModel(input.policy, state, completion.model);
  // A turn answered by another model than it asked for — or an auto-routed turn that
  // landed on a degraded one — is said, never silent (E7).
  const downgrade = hooks.model.downgrade?.(pctx, asked, completion.model);
  if (downgrade) await emit(input.ports.events, downgrade);
  return {
    content: completion.content ?? "",
    toolCalls: (completion.toolCalls ?? []).map((call) => ({ id: call.id, name: call.name, arguments: call.arguments })),
    meta: { model: completion.model, usage: completion.usage, interrupted: completion.interrupted, ...(completion.parts ? { parts: completion.parts } : {}), ...(completion.meta ? { native: completion.meta } : {}) },
  };
}

/**
 * The forced no-tools final synthesis (PRD 35 §6.2): a run that ended without an answer
 * gets ONE bounded extra call, with the stall policy's prompt and no tools, so the agent
 * always speaks (`brain/agentReplyLoop.ts`). The answer is shaped by the stall policy's
 * `settle` and recorded in the transcript. Returns null when the policy has no prompt,
 * the transport fails, or the model still says nothing — the caller keeps the outcome
 * it had.
 */
export async function synthesizeFinal(
  input: RunAgentInput,
  state: RunState,
  hooks: PolicyHooks,
  transcript: RunMessage[],
  pack: ContextPack,
  tally: RunTally,
  /** What stopped the run (a failure streak), so the closing prompt can name it. */
  why: SynthesisWhy = {},
): Promise<string | null> {
  if (input.signal?.aborted) return null;
  const pctx = policyContext(input, state, currentView(transcript, []), state.step, 0);
  const prompt = hooks.stall.synthesis?.(pctx, why);
  if (!prompt) return null;

  const decision = await hooks.model.resolve(pctx);
  // As in `completeTurn`: the policy's pick (absent on purpose after a pin was released),
  // else - only when no policy spoke - the pin.
  const model = decision ? decision.model : input.policy.pinnedModel;
  const fields = hooks.model.turnFields?.(pctx);
  const ask: RunMessage = { role: "user", content: prompt };
  const validation = specValidationSection(state);
  const validationSections = validation ? [validation] : [];
  let completion: ModelCompletion;
  try {
    completion = await measureModelRequest(input, state.step,
      {
        messages: [...withVolatileTail(transcript, pack, null, [...(input.ports.context.turnSections?.() ?? []), ...validationSections]), ask],
        ...(model ? { model, strict: decision?.strict ?? false } : {}),
        maxTokens: SYNTHESIS_MAX_TOKENS,
        // A transport records this turn as the run's forced closing one (and what stopped the run), never an ordinary turn.
        ...(why.failureStreak !== undefined ? { forcedFinish: why } : {}),
        ...askFields(fields),
        ...(renderTaskState(state.taskState) ? { progress: renderTaskState(state.taskState) } : {}),
      },
      'model_synthesis',
    );
  } catch (err) {
    // A resumable interruption (an eviction) is not "the model said nothing": it ends this tick and the host re-arms the run.
    if (isResumable(input, err)) throw err;
    return null;
  }
  adoptServedModel(input.policy, state, completion.model);
  tallyTurn(tally, completion.model, completion.usage);
  await emit(input.ports.events, {
    kind: "model.completed",
    step: state.step,
    ...(completion.model ? { model: completion.model } : {}),
    ...(completion.usage ? { usage: completion.usage } : {}),
  });

  const raw = completion.content ?? "";
  // A closing turn that said nothing is NO answer: the surface's `settle` shaping must not turn silence into a filler reply
  // (the Brain's `accept` answers an empty text "No response."), or the run would finish instead of failing on the breaker.
  if (!raw.trim()) return null;
  const output = hooks.stall.settle ? hooks.stall.settle(pctx, raw) : raw.trim();
  if (!output) return null;
  appendRows(input, transcript, ask, { role: "assistant", content: output });
  return output;
}

/**
 * Dispatch one tool call through the registry, so the capability gate holds at call
 * time and not only at advertisement. The registry owns the alias remap and the
 * "available tools" list in the unknown-tool error; calling `execute` directly would
 * skip both, and a model that hallucinates `list_dir` would be told the tool does
 * not exist instead of having it run. A tool the surface runs itself (`ports.extensions`)
 * is dispatched by the surface, under the same step signal, cap and coverage.
 *
 * A call whose arguments never parsed is DECLINED, not run with none: the kernel hands it
 * over as `args: {}`, and running it is how a file got written with no path. A surface's
 * own tools (`RunPorts.platform`) run the calls the shared registry does not, and the
 * first one that begins the work hands the run from analysis to code.
 *
 * A foreground command runs under a step signal that the run's Stop and an interrupting
 * steer both abort (`runToolWithWatch`, §6.3). The result is capped ONCE, to the serving
 * model's window (`resultCapFor`, §6.10) — what the model is served is what the read
 * coverage records.
 */
export async function dispatchCall(input: RunAgentInput, state: RunState, call: ParsedToolCall, watch: InterruptWatch, facts: TurnFacts = { refused: false }, step: number = state.step): Promise<LoopDispatchResult> {
  const invoke = () => dispatchCallCore(input, state, call, watch, facts, step);
  const verdict = (result: LoopDispatchResult) => result.isError || (result.data as { ok?: unknown } | null)?.ok === false ? 'failed' as const : 'completed' as const;
  return measureWorkflow(input.ports.events, workflowScope(input, step), 'dispatch', () => isSpawnTool(call.name)
    ? measureWorkflow(input.ports.events, workflowScope(input, step), 'spawn', invoke, verdict, input.signal)
    : invoke(), verdict, input.signal);
}

async function dispatchCallCore(input: RunAgentInput, state: RunState, call: ParsedToolCall, watch: InterruptWatch, facts: TurnFacts, step: number): Promise<LoopDispatchResult> {
  const { ports, signal } = input;
  if (call.malformed) return declineMalformedCall(ports, call, facts, step);
  if (blocksChildSpawn(input.task.dispatch, call.name)) {
    return { data: { ok: false, error: CHILD_SPAWN_REFUSAL }, isError: true };
  }
  const platform = ports.platform;
  const own = ownsCall(ports, call.name);
  if (platform && own && platform.handsOff?.(call.name) && state.model.phase === "plan") {
    state.model = reduceRunPolicy(state.model, { type: "hand_off" });
  }
  try {
    const box: { control?: LoopDispatchResult["control"]; failed?: boolean; killed?: boolean; kind?: "cached" | "neutral"; native?: NativeResult; observedData?: unknown } = {};
    const exec = async (name: string, args: unknown, stepSignal?: AbortSignal): Promise<unknown> => {
        const run = stepSignal ?? signal;
        const extension = ports.extensions;
        if (extension?.handles(name)) {
          const ran = await extension.dispatch(name, args as Record<string, unknown>, run);
          if (ran.isError) box.failed = true;
          if (ran.control) box.control = ran.control;
          return ran.data;
        }
        if (platform && own) {
          const result = await platform.execute(name, args as Record<string, unknown>, { ...(run ? { signal: run } : {}), progress: { rungs: state.stall?.rungs ?? {} }, callId: call.id, step });
          box.failed = result.isError === true;
          box.observedData = result.observedData;
          if (result.parts || result.meta) box.native = { ...(result.parts ? { parts: result.parts } : {}), ...(result.meta ? { meta: result.meta } : {}) };
          if (result.cached) box.kind = "cached";
          else if (result.neutral) box.kind = "neutral";
          // A command its signal killed answers in the policy's words: a steered message interrupted it, or the person's Stop did.
          if (result.aborted) {
            box.killed = true;
            return signal?.aborted ? stoppedResult(result.data) : interruptedResult(result.data);
          }
          return result.data;
        }
        if (!ports.capabilities) return { ok: false, error: "This run has no registry tool provider." };
        const result = await registryOf(ports).dispatch(name, args as Record<string, unknown>, { caps: ports.capabilities, ...(run ? { signal: run } : {}) });
        box.control = result.control;
        return extension?.shape ? extension.shape(name, result.data) : result.data;
    };
    // A surface whose runner watches the person's steers itself is not wrapped in a second watcher (`PlatformTools.watchesItself`).
    const data = own && platform?.watchesItself
      ? await exec(call.name, call.args)
      : await runToolWithWatch(exec, watch, signal, call.name, call.args, own ? platform?.interruptible : undefined);
    // A surface that guards its own context says its share; any other result is capped by the tool's table row, sized by the window.
    const servingModel = facts.model && facts.model !== "default" ? facts.model : state.model.model;
    const surfaceCap = own ? platform?.resultCap?.(servingModel) : undefined;
    const capped = capToolResult(call.name, data, surfaceCap ?? resultCapFor(call.name, ports.model, servingModel, data));
    // A surface's own tool says for itself whether it failed; a registry tool says so with `ok: false`.
    // A call that never started (a steer was already waiting) did not fail: its dispatch is not an error, so the breaker does not count it.
    // Like any dispatch that did not fail, it clears the failure streak (as a kill does): the streak is reset to 0, not held.
    const failed = box.failed === true || (!own && !!capped && (capped as { ok?: unknown }).ok === false && (capped as { skipped?: unknown }).skipped !== true);
    const dispatched: LoopDispatchResult = { data: capped, ...(box.control ? { control: box.control } : {}), ...(failed ? { isError: true } : {}) };
    if (box.kind) callKinds.set(dispatched, box.kind);
    if (state.specValidation && !box.killed) observedToolData.set(dispatched, box.observedData ?? data);
    if (box.native) nativeResults.set(dispatched, box.native);
    if (box.killed) killedResults.add(dispatched);
    return dispatched;
  } catch (err) {
    // A resumable interruption (a platform eviction) is not the tool's failure to hand the model: it ends this tick and the host re-arms.
    if (signal?.aborted || isResumable(input, err)) throw err;
    const reason = err instanceof Error ? err.message : String(err);
    return { data: { ok: false, error: reason }, isError: true };
  }
}

/**
 * The result a call with unusable arguments gets INSTEAD of being run. The wording, and the
 * cut-off-vs-unparseable decision, belong to the kernel that sets the flag; the surface adds
 * only its own retry advice (`PlatformTools.malformed`), or answers the call in its own words
 * (`answer`). The tool never ran, but the kernel counts the declined call as a failed
 * dispatch, as it always has.
 */
async function declineMalformedCall(ports: RunPorts, call: ParsedToolCall, facts: TurnFacts, step: number): Promise<LoopDispatchResult> {
  const truncated = facts.interruption === "truncated";
  const policy = ports.platform?.malformed;
  const answered = await policy?.answer?.({ id: call.id, name: call.name, arguments: call.raw.arguments }, { step, truncated });
  if (answered) {
    facts.refused = true;
    return { data: answered.data, ...(answered.isError ? { isError: true } : {}) };
  }
  const outcome = malformedCallOutcome(call, truncated, truncated ? policy?.retryHint : undefined);
  facts.refused = true;
  policy?.refused?.({ name: call.name, arguments: call.raw.arguments }, truncated, outcome);
  return { data: outcome, isError: true };
}
